 c=json.loads((ROOT/'data/turnout/priority-set.json').read_text());rs=own_receipts();receipts={r['id']:r for r in rs};findings=json.loads((MAPS/'county-findings.json').read_text());investigations=json.loads((MAPS/'county-investigations.json').read_text());fs,nq=verify();counts=nq['county_counts'];pdfqa=json.loads((MAPS/'qa/pdf-render.json').read_text());pdfby={rid:p for p in pdfqa['pdfs'] for rid in p['request_ids']}
